),
incoming_ids as (
  select value->>'id' as id
  from incoming, jsonb_array_elements(incoming.roles) as value
),
kept as (
  select coalesce(jsonb_agg(r.value), '[]'::jsonb) as roles
  from public.workspaces w
  join me using (owner_id)
  cross join lateral jsonb_array_elements(w.data->'roles') as r(value)
  where r.value->>'id' not in (select id from incoming_ids)
)
update public.workspaces w
set
  data = jsonb_set(w.data, '{roles}', (select roles from kept) || (select roles from incoming)),
  revision = w.revision + 1,
  updated_at = now()
from me
where w.owner_id = me.owner_id;

-- Verify: should list all 20 templates for your workspace.
with params as (
  select 'handysolverteam@gmail.com'::text as owner_email      -- <<< keep in sync with above
)
select r.value->>'id' as id,
       r.value->>'name' as name,
       jsonb_array_length(r.value->'fields') as fields
from public.workspaces w
join auth.users u on u.id = w.owner_id
cross join lateral jsonb_array_elements(w.data->'roles') as r(value), params p
where u.email = p.owner_email
order by name;
